// ============================================================
// 输入：msg.payload = 对象数组，每个对象包含 itemName 和 value
//      value 可能是真数组、类数组对象（{0:..,1:..}）或单值
// 输出：msg.payload = 合并后的对象数组，每个对象第一个键为 index（从1开始）
//      例如 [{"index":1,"name":"AX1","status":1}, {"index":2,"name":"AX2","status":3}, ...]
// ============================================================

// 1. 将 value 统一转为数组的辅助函数
function toArray(val) {
    if (Array.isArray(val)) {
        return val;
    }
    if (val && typeof val === "object") {
        // 类数组对象：按数字键排序后取值
        return Object.keys(val)
            .sort((a, b) => Number(a) - Number(b))
            .map(k => val[k]);
    }
    // 单值（字符串、数字等）包装成数组
    return [val];
}

// 2. 将每个 item 拆分为子数组
const nested = [];

msg.payload.forEach(item => {
    const key = item.itemName;
    if (!key || key === "undefined") return; // 跳过无效键名

    const values = toArray(item.value);
    const subArr = values.map(v => ({ [key]: v }));
    nested.push(subArr);
});

// 3. 按相同索引合并子数组，并添加 index 字段
if (nested.length === 0) {
    msg.payload = [];
    return msg;
}

const minLen = Math.min(...nested.map(arr => arr.length));
const result = [];

for (let i = 0; i < minLen; i++) {
    const merged = {};
    for (const subArr of nested) {
        const obj = subArr[i];
        if (obj) {
            Object.assign(merged, obj);
        }
    }
    // 在最前面插入 index 字段，值为 i+1
    result.push({ index: i + 1, ...merged });
}

msg.payload = result;
return msg;

// 输入：
//   msg.payload = 待过滤的 JSON 数组
//   msg.filters = 过滤条件数组（可选，未传则使用下方默认值）
// 输出：
//   msg.payload = 过滤后的数组

const data = msg.payload;

// 过滤条件：key 字段名，op 运算符（"==" 或 "!="），value 比较值
const filters = msg.filters || [

      {key: "channelNo",     op: "!=", value: 0},
      {key: "type",          op: "==", value: 2}




];

// 逐条判断，全部条件满足才保留
const result = data.filter(item => {
    return filters.every(f => {
        if (f.op === "==") {
            return item[f.key] === f.value;
        } else if (f.op === "!=") {
            return item[f.key] !== f.value;
        }
        return true; // 未知运算符则忽略
    });
});

msg.payload = result;
return msg;

